class CountingClient(FakeClient):
    def __init__(self, raw=None):
        super().__init__(raw)
        self.raw_calls = 0

    def get_raw_spans(self, trace_id):
        self.raw_calls += 1
        return super().get_raw_spans(trace_id)


def truncated_raw():
    raw = json.loads(json.dumps(recorded("raw_spans.json")["spans"]))
